def equation(gate_voltage_abs: np.ndarray, parameters: np.ndarray) -> np.ndarray:
    """Equação empírica para log10(|ID|/A) ao longo da curva de transferência."""
    """Cubic empirical equation for log10(|ID|/A) along the saturation transfer curve."""

    a, b, c, d = parameters
    return (a + b * gate_voltage_abs + c * (gate_voltage_abs)**2 + d * (gate_voltage_abs)**3) / np.log(10)
